from sys import stderr

def main():
	print(solve(readcase()))

def readcase():
	(n, m) = readints()
	mtx = []
	for _ in range(n):
		mtx.append(readints())
		assert len(mtx[0]) == m
	return mtx

def readints():
	return [int(f) for f in input().split()]

def solve(m):
	best = 0
	(nrows, ncols) = (len(m), len(m[0]))
	for irow in range(nrows):
		for icol in range(ncols):
			upperrow = [m[irow][icol]] * (ncols - icol)
			cur = m[irow][icol]
			for jrow in range(irow, nrows):
				prev = m[irow][icol]
				goodcols = 0
				for jcol in range(icol, ncols):
					prev = gcd(prev, gcd(upperrow[jcol - icol], m[jrow][jcol]))
					if prev == 1:
						upperrow[jcol - icol:] = [1] * (ncols - jcol)
						break
					goodcols += 1
					upperrow[jcol - icol] = prev
				if best >= (nrows - irow) * goodcols:
					break
				best = max(best, (jrow - irow + 1) * goodcols)
	return best

def gcd(a, b):
	(a, b) = (max(a, b), min(a, b))
	while b != 0:
		(a, b) = (b, a % b)
	return a
